import os
import json
import re
from typing import Any, Dict, List, Literal, Optional, Tuple, Union, AsyncGenerator

import anyio
import httpx
from fastapi import FastAPI, HTTPException, Request
from fastapi.responses import JSONResponse, StreamingResponse
from pydantic import BaseModel, Field

from cerebras.cloud.sdk import Cerebras
from parallel import Parallel
from parallel.types import TaskSpecParam, TextSchemaParam


SOURCE_NOTES = "[page:0][page:1][page:2][page:3]"


CEREBRAS_API_KEY = os.environ.get("CEREBRAS_API_KEY")
EXA_API_KEY = os.environ.get("EXA_API_KEY")
PARALLEL_API_KEY = os.environ.get("PARALLEL_API_KEY")

CEREBRAS_MODEL = os.environ.get("CEREBRAS_MODEL", "zai-glm-4.7")
CEREBRAS_TEMPERATURE_DEFAULT = float(os.environ.get("CEREBRAS_TEMPERATURE_DEFAULT", "1"))
CEREBRAS_TOP_P_DEFAULT = float(os.environ.get("CEREBRAS_TOP_P_DEFAULT", "0.95"))
CEREBRAS_MAX_COMPLETION_TOKENS_DEFAULT = int(os.environ.get("CEREBRAS_MAX_COMPLETION_TOKENS_DEFAULT", "65000"))

EXA_BASE_URL = os.environ.get("EXA_BASE_URL", "")
EXA_SEARCH_PATH = os.environ.get("EXA_SEARCH_PATH", "/search")
EXA_TYPE_FAST = os.environ.get("EXA_TYPE_FAST", "fast")
EXA_NUM_RESULTS = int(os.environ.get("EXA_NUM_RESULTS", "100"))
EXA_TIMEOUT_SECONDS = float(os.environ.get("EXA_TIMEOUT_SECONDS", "60"))
EXA_MAX_CONCURRENCY = int(os.environ.get("EXA_MAX_CONCURRENCY", "8"))
EXA_TEXT_MAX_CHARS_PER_RESULT = int(os.environ.get("EXA_TEXT_MAX_CHARS_PER_RESULT", "2000"))
EXA_CONTEXT_MAX_CHARS = int(os.environ.get("EXA_CONTEXT_MAX_CHARS", "180000"))

PLANNER_MAX_TOKENS = int(os.environ.get("PLANNER_MAX_TOKENS", "2048"))
PLANNER_TEMPERATURE = float(os.environ.get("PLANNER_TEMPERATURE", "0.2"))
PLANNER_TOP_P = float(os.environ.get("PLANNER_TOP_P", "0.95"))
MAX_SEARCH_QUERIES = int(os.environ.get("MAX_SEARCH_QUERIES", "24"))

PARALLEL_PROCESSOR = os.environ.get("PARALLEL_PROCESSOR", "ultra8x")
PARALLEL_API_TIMEOUT_SECONDS = int(os.environ.get("PARALLEL_API_TIMEOUT_SECONDS", "3600"))
PARALLEL_INPUT_MAX_CHARS = int(os.environ.get("PARALLEL_INPUT_MAX_CHARS", "15000"))
PARALLEL_REPORT_MAX_CHARS_FOR_CONTEXT = int(os.environ.get("PARALLEL_REPORT_MAX_CHARS_FOR_CONTEXT", "240000"))

FINAL_CONTEXT_MAX_CHARS = int(os.environ.get("FINAL_CONTEXT_MAX_CHARS", "260000"))

HTTP_USER_AGENT = os.environ.get("HTTP_USER_AGENT", "search-research-router/1.0")

app = FastAPI()

_cerebras_client: Optional[Cerebras] = None


class ChatMessage(BaseModel):
    role: Literal["system", "user", "assistant", "tool"]
    content: str


class ChatRequest(BaseModel):
    mode: Literal["search", "research"] = Field(...)
    messages: List[ChatMessage] = Field(...)
    stream: bool = Field(default=True)
    temperature: Optional[float] = Field(default=None)
    top_p: Optional[float] = Field(default=None)
    max_completion_tokens: Optional[int] = Field(default=None)
    system_prompt: Optional[str] = Field(default=None)


class ChatResponse(BaseModel):
    content: str


def _require_env(var_name: str, value: Optional[str]) -> str:
    if not value:
        raise HTTPException(status_code=500, detail=f"Missing required environment variable: {var_name}")
    return value


def _get_cerebras_client() -> Cerebras:
    global _cerebras_client
    if _cerebras_client is None:
        _require_env("CEREBRAS_API_KEY", CEREBRAS_API_KEY)
        _cerebras_client = Cerebras(api_key=CEREBRAS_API_KEY)
    return _cerebras_client


def _normalize_messages(messages: List[ChatMessage], system_prompt: Optional[str]) -> List[Dict[str, str]]:
    out: List[Dict[str, str]] = []
    if system_prompt is not None and system_prompt.strip():
        if not messages or messages[0].role != "system":
            out.append({"role": "system", "content": system_prompt})
        else:
            out.append({"role": "system", "content": system_prompt})
            out.extend([{"role": m.role, "content": m.content} for m in messages[1:]])
            return out
    out.extend([{"role": m.role, "content": m.content} for m in messages])
    if not out or out[0]["role"] != "system":
        out.insert(0, {"role": "system", "content": ""})
    return out


def _extract_last_user_question(messages: List[Dict[str, str]]) -> str:
    for m in reversed(messages):
        if m.get("role") == "user" and (m.get("content") or "").strip():
            return m["content"].strip()
    raise HTTPException(status_code=400, detail="No user message found in messages")


def _safe_json_loads(text: str) -> Any:
    try:
        return json.loads(text)
    except Exception:
        s = text.strip()
        m = re.search(r"\{.*\}", s, flags=re.DOTALL)
        if m:
            try:
                return json.loads(m.group(0))
            except Exception:
                pass
        m = re.search(r"\[.*\]", s, flags=re.DOTALL)
        if m:
            try:
                return json.loads(m.group(0))
            except Exception:
                pass
        raise


def _dedupe_preserve_order(items: List[str]) -> List[str]:
    seen = set()
    out: List[str] = []
    for x in items:
        k = x.strip()
        if not k:
            continue
        if k not in seen:
            seen.add(k)
            out.append(k)
    return out


def _truncate_text(s: str, max_chars: int) -> str:
    if max_chars <= 0:
        return ""
    if len(s) <= max_chars:
        return s
    return s[:max_chars]


async def _cerebras_plan_queries(messages: List[Dict[str, str]]) -> List[str]:
    client = _get_cerebras_client()
    question = _extract_last_user_question(messages)
    planner_system = (
        "Generate web search queries for Exa fast web search. "
        "Return STRICT JSON with this schema: {\"queries\": [\"...\"]}. "
        "Queries must be short, keyword-focused, and collectively cover the user question. "
        "Generate as many queries as needed, but avoid redundancy."
    )
    planner_messages = [{"role": "system", "content": planner_system}, {"role": "user", "content": question}]
    resp = await anyio.to_thread.run_sync(
        lambda: client.chat.completions.create(
            model=CEREBRAS_MODEL,
            messages=planner_messages,
            stream=False,
            max_completion_tokens=PLANNER_MAX_TOKENS,
            temperature=PLANNER_TEMPERATURE,
            top_p=PLANNER_TOP_P,
        )
    )
    content = ""
    try:
        content = (resp.choices[0].message.content or "").strip()
    except Exception:
        content = ""
    if not content:
        raise HTTPException(status_code=500, detail="Query planner returned empty output")
    try:
        obj = _safe_json_loads(content)
    except Exception:
        lines = [ln.strip("- ").strip() for ln in content.splitlines() if ln.strip()]
        queries = _dedupe_preserve_order(lines)
        if not queries:
            raise HTTPException(status_code=500, detail="Query planner output was not parseable")
        return queries[:MAX_SEARCH_QUERIES]
    queries_raw = obj.get("queries") if isinstance(obj, dict) else None
    if not isinstance(queries_raw, list):
        raise HTTPException(status_code=500, detail="Query planner JSON missing 'queries' list")
    queries = _dedupe_preserve_order([str(q) for q in queries_raw])
    if not queries:
        raise HTTPException(status_code=500, detail="Query planner produced empty 'queries'")
    return queries[:MAX_SEARCH_QUERIES]


async def _exa_search_one(client: httpx.AsyncClient, query: str) -> Dict[str, Any]:
    _require_env("EXA_API_KEY", EXA_API_KEY)
    url = EXA_BASE_URL.rstrip("/") + EXA_SEARCH_PATH
    headers = {"x-api-key": EXA_API_KEY, "User-Agent": HTTP_USER_AGENT, "Content-Type": "application/json"}
    payload: Dict[str, Any] = {"query": query, "type": EXA_TYPE_FAST, "num_results": EXA_NUM_RESULTS}
    r = await client.post(url, headers=headers, json=payload)
    if r.status_code >= 400:
        raise HTTPException(status_code=502, detail=f"Exa API error {r.status_code}: {r.text}")
    try:
        return r.json()
    except Exception:
        raise HTTPException(status_code=502, detail="Exa API returned non-JSON response")


def _exa_compact_results_to_context(exa_payloads: List[Tuple[str, Dict[str, Any]]]) -> str:
    parts: List[str] = []
    for q, payload in exa_payloads:
        results = payload.get("results")
        if not isinstance(results, list):
            continue
        parts.append(f"QUERY: {q}")
        for i, item in enumerate(results, start=1):
            if not isinstance(item, dict):
                continue
            title = str(item.get("title") or "")
            url = str(item.get("url") or "")
            published = str(item.get("publishedDate") or "")
            author = str(item.get("author") or "")
            highlights = item.get("highlights")
            summary = str(item.get("summary") or "")
            text = str(item.get("text") or "")
            snippet = ""
            if isinstance(highlights, list) and highlights:
                snippet = " ".join([str(h) for h in highlights if h])
            elif summary:
                snippet = summary
            elif text:
                snippet = text
            snippet = re.sub(r"\s+", " ", snippet).strip()
            snippet = _truncate_text(snippet, EXA_TEXT_MAX_CHARS_PER_RESULT)
            if not url and not title and not snippet:
                continue
            line = f"{i}. {title}\nURL: {url}"
            if published:
                line += f"\nPublished: {published}"
            if author:
                line += f"\nAuthor: {author}"
            if snippet:
                line += f"\nExcerpt: {snippet}"
            parts.append(line)
        parts.append("")
    context = "\n".join(parts).strip()
    return _truncate_text(context, EXA_CONTEXT_MAX_CHARS)


async def _exa_fast_search_context(queries: List[str]) -> str:
    limits = httpx.Limits(max_connections=EXA_MAX_CONCURRENCY, max_keepalive_connections=EXA_MAX_CONCURRENCY)
    timeout = httpx.Timeout(EXA_TIMEOUT_SECONDS)
    async with httpx.AsyncClient(timeout=timeout, limits=limits) as client:
        sem = anyio.Semaphore(EXA_MAX_CONCURRENCY)

        async def run_one(q: str) -> Tuple[str, Dict[str, Any]]:
            async with sem:
                payload = await _exa_search_one(client, q)
                return q, payload

        payloads = await anyio.gather(*[run_one(q) for q in queries])
    return _exa_compact_results_to_context(payloads)


def _parallel_deep_research_sync(prompt: str) -> str:
    _require_env("PARALLEL_API_KEY", PARALLEL_API_KEY)
    if len(prompt) > PARALLEL_INPUT_MAX_CHARS:
        prompt = prompt[:PARALLEL_INPUT_MAX_CHARS]
    client = Parallel(api_key=PARALLEL_API_KEY)
    task_spec = TaskSpecParam(output_schema=TextSchemaParam())
    last_error: Optional[Exception] = None
    for processor in [PARALLEL_PROCESSOR, "ultra", "pro", "base"]:
        try:
            run = client.task_run.create(input=prompt, processor=processor, task_spec=task_spec)
            result = client.task_run.result(run.run_id, api_timeout=PARALLEL_API_TIMEOUT_SECONDS)
            output = getattr(result, "output", None)
            if output is None:
                raise RuntimeError("Parallel returned empty output")
            if isinstance(output, str):
                return output
            text = getattr(output, "text", None)
            if isinstance(text, str) and text.strip():
                return text
            try:
                return json.dumps(output, ensure_ascii=False)
            except Exception:
                return str(output)
        except Exception as e:
            last_error = e
            continue
    raise HTTPException(status_code=502, detail=f"Parallel Deep Research failed: {str(last_error) if last_error else 'unknown error'}")


async def _parallel_deep_research_text(prompt: str) -> str:
    return await anyio.to_thread.run_sync(lambda: _parallel_deep_research_sync(prompt))


def _build_final_system_prompt() -> str:
    return (
        "You are a precise, technical assistant. "
        "Use the provided context to answer the user's question. "
        "If the context is insufficient, state what is missing and what would be needed. "
        "Prefer concrete, verifiable statements and reference URLs when present in the context."
    )


def _build_context_block(mode: str, context: str) -> str:
    context = _truncate_text(context, FINAL_CONTEXT_MAX_CHARS)
    return f"MODE: {mode}\nCONTEXT:\n{context}".strip()


def _merge_messages_with_context(base_messages: List[Dict[str, str]], mode: str, context: str) -> List[Dict[str, str]]:
    user_question = _extract_last_user_question(base_messages)
    system_prompt = _build_final_system_prompt()
    context_block = _build_context_block(mode, context)
    out: List[Dict[str, str]] = [{"role": "system", "content": system_prompt}]
    out.append({"role": "user", "content": f"{user_question}\n\n{context_block}"})
    return out


async def _cerebras_stream_text(
    request: Request,
    messages: List[Dict[str, str]],
    temperature: float,
    top_p: float,
    max_completion_tokens: int,
) -> AsyncGenerator[str, None]:
    client = _get_cerebras_client()
    stream = await anyio.to_thread.run_sync(
        lambda: client.chat.completions.create(
            model=CEREBRAS_MODEL,
            messages=messages,
            stream=True,
            max_completion_tokens=max_completion_tokens,
            temperature=temperature,
            top_p=top_p,
        )
    )
    for chunk in stream:
        if await request.is_disconnected():
            break
        try:
            delta = chunk.choices[0].delta
            content = getattr(delta, "content", None)
            if content:
                yield f"data: {content}\n\n"
        except Exception:
            continue
    if not await request.is_disconnected():
        yield "data: [DONE]\n\n"


async def _cerebras_nonstream_text(
    messages: List[Dict[str, str]],
    temperature: float,
    top_p: float,
    max_completion_tokens: int,
) -> str:
    client = _get_cerebras_client()
    resp = await anyio.to_thread.run_sync(
        lambda: client.chat.completions.create(
            model=CEREBRAS_MODEL,
            messages=messages,
            stream=False,
            max_completion_tokens=max_completion_tokens,
            temperature=temperature,
            top_p=top_p,
        )
    )
    try:
        return (resp.choices[0].message.content or "").strip()
    except Exception:
        return ""


async def _build_context_for_mode(mode: Literal["search", "research"], normalized_messages: List[Dict[str, str]]) -> str:
    question = _extract_last_user_question(normalized_messages)
    if mode == "search":
        _require_env("EXA_API_KEY", EXA_API_KEY)
        queries = await _cerebras_plan_queries(normalized_messages)
        search_context = await _exa_fast_search_context(queries)
        return f"USER_QUESTION:\n{question}\n\nEXA_FAST_SEARCH_QUERIES:\n{json.dumps(queries, ensure_ascii=False)}\n\nEXA_FAST_SEARCH_RESULTS:\n{search_context}"
    _require_env("PARALLEL_API_KEY", PARALLEL_API_KEY)
    report = await _parallel_deep_research_text(question)
    report = _truncate_text(report, PARALLEL_REPORT_MAX_CHARS_FOR_CONTEXT)
    return f"USER_QUESTION:\n{question}\n\nPARALLEL_DEEP_RESEARCH_REPORT:\n{report}"


@app.get("/health")
async def health() -> JSONResponse:
    return JSONResponse(
        {
            "ok": True,
            "source_notes": SOURCE_NOTES,
            "cerebras_model": CEREBRAS_MODEL,
            "exa_type_fast": EXA_TYPE_FAST,
            "exa_num_results": EXA_NUM_RESULTS,
            "parallel_processor": PARALLEL_PROCESSOR,
        }
    )


@app.post("/v1/chat")
async def chat(req: ChatRequest, request: Request) -> Union[JSONResponse, StreamingResponse]:
    temperature = req.temperature if req.temperature is not None else CEREBRAS_TEMPERATURE_DEFAULT
    top_p = req.top_p if req.top_p is not None else CEREBRAS_TOP_P_DEFAULT
    max_completion_tokens = (
        req.max_completion_tokens if req.max_completion_tokens is not None else CEREBRAS_MAX_COMPLETION_TOKENS_DEFAULT
    )

    normalized = _normalize_messages(req.messages, req.system_prompt)
    context = await _build_context_for_mode(req.mode, normalized)
    final_messages = _merge_messages_with_context(normalized, req.mode, context)

    if req.stream:
        gen = _cerebras_stream_text(request, final_messages, temperature, top_p, max_completion_tokens)
        return StreamingResponse(gen, media_type="text/event-stream")

    content = await _cerebras_nonstream_text(final_messages, temperature, top_p, max_completion_tokens)
    return JSONResponse(ChatResponse(content=content).model_dump())


if __name__ == "__main__":
    import uvicorn

    host = os.environ.get("HOST", "0.0.0.0")
    port = int(os.environ.get("PORT", "8000"))
    uvicorn.run(app, host=host, port=port)
