    planner_messages = [{"role": "system", "content": planner_system}, {"role": "user", "content": question}]
    resp = await asyncio.to_thread(
        lambda: client.chat.completions.create(
            model=CEREBRAS_MODEL,
            messages=planner_messages,
            stream=False,
            max_completion_tokens=PLANNER_MAX_COMPLETION_TOKENS,
            temperature=PLANNER_TEMPERATURE,
            top_p=PLANNER_TOP_P,
        )
    )
    content = ""
    try:
        content = (resp.choices[0].message.content or "").strip()
    except Exception:
        content = ""
    if not content:
        raise HTTPException(status_code=500, detail="Query planner returned empty output")
    try:
        obj = _safe_json_loads(content)
    except Exception:
        lines = [ln.strip().lstrip("-").strip() for ln in content.splitlines() if ln.strip()]
        queries = _dedupe_preserve_order(lines)
        if not queries:
            raise HTTPException(status_code=500, detail="Query planner output was not parseable")
        return queries[:MAX_SEARCH_QUERIES]
    queries_raw = obj.get("queries") if isinstance(obj, dict) else None
    if not isinstance(queries_raw, list):
        raise HTTPException(status_code=500, detail="Query planner JSON missing 'queries' list")
    queries = _dedupe_preserve_order([str(q) for q in queries_raw])
    if not queries:
        raise HTTPException(status_code=500, detail="Query planner produced empty 'queries'")
    return queries[:MAX_SEARCH_QUERIES]


async def _exa_search_one(client: httpx.AsyncClient, query: str) -> Dict[str, Any]:
    _require_env("EXA_API_KEY", EXA_API_KEY)
    url = EXA_BASE_URL.rstrip("/") + EXA_SEARCH_PATH
    headers = {"x-api-key": EXA_API_KEY, "User-Agent": HTTP_USER_AGENT, "Content-Type": "application/json"}
    payload: Dict[str, Any] = {
        "query": query,
        "type": EXA_TYPE_FAST,
        "num_results": EXA_NUM_RESULTS,
        "contents": {
            "text": True,
            "highlights": True,
            "summary": True,
        },
    }
    r = await client.post(url, headers=headers, json=payload)
    if r.status_code >= 400:
        raise HTTPException(status_code=502, detail=f"Exa API error {r.status_code}: {r.text}")
    try:
        return r.json()
    except Exception:
        raise HTTPException(status_code=502, detail="Exa API returned non-JSON response")


def _exa_compact_results_to_context(exa_payloads: List[Tuple[str, Dict[str, Any]]]) -> str:
    parts: List[str] = []
    for q, payload in exa_payloads:
        results = payload.get("results")
        if not isinstance(results, list):
            continue
        parts.append(f"QUERY: {q}")
        for i, item in enumerate(results, start=1):
            if not isinstance(item, dict):
                continue
            title = str(item.get("title") or "")
            url = str(item.get("url") or "")
            published = str(item.get("publishedDate") or "")
            author = str(item.get("author") or "")
            highlights = item.get("highlights")
            summary = item.get("summary")
            text = item.get("text")

            excerpt = ""
            if isinstance(highlights, list) and highlights:
                excerpt = " ".join([str(h) for h in highlights if h])
            elif isinstance(summary, str) and summary.strip():
                excerpt = summary
            elif isinstance(text, str) and text.strip():
                excerpt = text

            excerpt = re.sub(r"\s+", " ", excerpt).strip()
            if EXA_MAX_EXCERPT_CHARS_PER_RESULT > 0 and len(excerpt) > EXA_MAX_EXCERPT_CHARS_PER_RESULT:
                excerpt = excerpt[:EXA_MAX_EXCERPT_CHARS_PER_RESULT]

            if not url and not title and not excerpt:
                continue

            block = f"{i}. {title}\nURL: {url}"
            if published:
                block += f"\nPublished: {published}"
            if author:
                block += f"\nAuthor: {author}"
            if excerpt:
                block += f"\nExcerpt: {excerpt}"
            parts.append(block)
        parts.append("")
    context = "\n".join(parts).strip()
    return _soft_trim_to_budget(context, EXA_CONTEXT_SOFT_CHAR_BUDGET)


async def _exa_fast_search_context(queries: List[str]) -> str:
    limits = httpx.Limits(max_connections=EXA_MAX_CONCURRENCY, max_keepalive_connections=EXA_MAX_CONCURRENCY)
    timeout = httpx.Timeout(EXA_TIMEOUT_SECONDS)
    async with httpx.AsyncClient(timeout=timeout, limits=limits) as client:
        sem = asyncio.Semaphore(EXA_MAX_CONCURRENCY)

        async def run_one(q: str) -> Tuple[str, Dict[str, Any]]:
            async with sem:
                payload = await _exa_search_one(client, q)
                return q, payload

        tasks = [asyncio.create_task(run_one(q)) for q in queries]
        payloads = await asyncio.gather(*tasks)
    return _exa_compact_results_to_context(payloads)


def _parallel_deep_research_sync(prompt: str) -> str:
    _require_env("PARALLEL_API_KEY", PARALLEL_API_KEY)
    prompt = prompt.strip()
    if not prompt:
        raise HTTPException(status_code=400, detail="Empty research prompt")
    if len(prompt) > PARALLEL_INPUT_MAX_CHARS:
        prompt = prompt[:PARALLEL_INPUT_MAX_CHARS]
    client = Parallel(api_key=PARALLEL_API_KEY)
    task_spec = TaskSpecParam(output_schema=TextSchemaParam())
    last_error: Optional[Exception] = None
    for processor in [PARALLEL_PROCESSOR_PRIMARY, PARALLEL_PROCESSOR_FALLBACK_1, PARALLEL_PROCESSOR_FALLBACK_2]:
        try:
            task_run = client.task_run.create(input=prompt, processor=processor, task_spec=task_spec)
            run_result = client.task_run.result(task_run.run_id, api_timeout=PARALLEL_API_TIMEOUT_SECONDS)
            output = getattr(run_result, "output", None)
            if output is None:
                raise RuntimeError("Parallel returned empty output")
            if isinstance(output, str):
                return output
            text = getattr(output, "text", None)
            if isinstance(text, str) and text.strip():
                return text
            try:
                return json.dumps(output, ensure_ascii=False)
            except Exception:
                return str(output)
        except Exception as e:
            last_error = e
            continue
    raise HTTPException(status_code=502, detail=f"Parallel Deep Research failed: {str(last_error) if last_error else 'unknown error'}")


async def _parallel_deep_research_text(prompt: str) -> str:
    report = await asyncio.to_thread(lambda: _parallel_deep_research_sync(prompt))
    if PARALLEL_REPORT_MAX_CHARS > 0 and len(report) > PARALLEL_REPORT_MAX_CHARS:
        report = report[:PARALLEL_REPORT_MAX_CHARS]
    return report


def _build_final_system_prompt() -> str:
    return (
        "You are a precise, technical assistant. "
        "Use the provided context to answer the user's question. "
        "When possible, include relevant URLs from the context. "
        "If the context is insufficient, state what is missing and what would be needed."
    )


def _merge_messages_with_context(base_messages: List[Dict[str, str]], mode: str, context: str) -> List[Dict[str, str]]:
    user_question = _extract_last_user_question(base_messages)
    system_prompt = _build_final_system_prompt()
    context = _soft_trim_to_budget(context, FINAL_CONTEXT_SOFT_CHAR_BUDGET)
    out: List[Dict[str, str]] = [{"role": "system", "content": system_prompt}]
    out.append({"role": "user", "content": f"{user_question}\n\nMODE: {mode}\nCONTEXT:\n{context}"})
    return out


async def _cerebras_stream_text(
    request: Request,
    messages: List[Dict[str, str]],
    temperature: float,
    top_p: float,
) -> AsyncGenerator[str, None]:
    client = _get_cerebras_client()
    stream = await asyncio.to_thread(
        lambda: client.chat.completions.create(
            model=CEREBRAS_MODEL,
            messages=messages,
            stream=True,
            max_completion_tokens=CEREBRAS_MAX_COMPLETION_TOKENS,
            temperature=temperature,
            top_p=top_p,
        )
    )
    for chunk in stream:
        if await request.is_disconnected():
            break
        try:
            delta = chunk.choices[0].delta
            content = getattr(delta, "content", None)
            if content:
                yield f"data: {content}\n\n"
        except Exception:
            continue
    if not await request.is_disconnected():
        yield "data: [DONE]\n\n"


async def _cerebras_nonstream_text(
    messages: List[Dict[str, str]],
    temperature: float,
    top_p: float,
) -> str:
    client = _get_cerebras_client()
    resp = await asyncio.to_thread(
        lambda: client.chat.completions.create(
            model=CEREBRAS_MODEL,
            messages=messages,
            stream=False,
            max_completion_tokens=CEREBRAS_MAX_COMPLETION_TOKENS,
            temperature=temperature,
            top_p=top_p,
        )
    )
    try:
        return (resp.choices[0].message.content or "").strip()
    except Exception:
        return ""


async def _build_context_for_mode(mode: Literal["search", "research"], normalized_messages: List[Dict[str, str]]) -> str:
    question = _extract_last_user_question(normalized_messages)
    if mode == "search":
        _require_env("EXA_API_KEY", EXA_API_KEY)
        queries = await _cerebras_plan_queries(normalized_messages)
        search_context = await _exa_fast_search_context(queries)
        return (
            "USER_QUESTION:\n"
            + question
            + "\n\nEXA_FAST_SEARCH:\n"
            + json.dumps({"type": EXA_TYPE_FAST, "num_results": EXA_NUM_RESULTS, "queries": queries}, ensure_ascii=False)
            + "\n\nEXA_RESULTS:\n"
            + search_context
        )
    _require_env("PARALLEL_API_KEY", PARALLEL_API_KEY)
    report = await _parallel_deep_research_text(question)
    return "USER_QUESTION:\n" + question + "\n\nPARALLEL_DEEP_RESEARCH_REPORT:\n" + report


