async def _sleep_backoff(attempt: int) -> None:
    delay = min(HTTP_RETRY_MAX_DELAY_S, HTTP_RETRY_BASE_DELAY_S * (2 ** max(0, attempt - 1)))
    delay = delay * (0.85 + 0.3 * (hashlib.sha256(os.urandom(8)).digest()[0] / 255.0))
    await asyncio.sleep(delay)


async def _http_json_with_retries(
    client: httpx.AsyncClient,
    method: str,
    url: str,
    headers: Dict[str, str],
    json_body: Optional[Dict[str, Any]] = None,
    timeout_s: Optional[float] = None,
) -> Dict[str, Any]:
    last_text = ""
    last_status = 0
    for attempt in range(1, HTTP_MAX_RETRIES + 1):
        try:
            r = await client.request(method, url, headers=headers, json=json_body, timeout=timeout_s)
            last_status = r.status_code
            last_text = r.text
            if r.status_code == 429 or (500 <= r.status_code <= 599):
                await _sleep_backoff(attempt)
                continue
            if r.status_code >= 400:
                raise HTTPException(status_code=502, detail=f"Upstream error {r.status_code}: {r.text}")
            try:
                return r.json()
            except Exception:
                raise HTTPException(status_code=502, detail="Upstream returned non-JSON response")
        except HTTPException:
            raise
        except (httpx.TimeoutException, httpx.NetworkError):
            await _sleep_backoff(attempt)
            continue
        except Exception:
            await _sleep_backoff(attempt)
            continue
    raise HTTPException(status_code=502, detail=f"Upstream error after retries (status={last_status}): {last_text}")


def _cerebras_response_format_json_schema(schema_name: str, schema: Dict[str, Any]) -> Dict[str, Any]:
    return {"type": "json_schema", "json_schema": {"name": schema_name, "strict": True, "schema": schema}}


def _safe_json_loads(text: str) -> Any:
    try:
        return json.loads(text)
    except Exception:
        s = text.strip()
        m = re.search(r"\{.*\}", s, flags=re.DOTALL)
        if m:
            return json.loads(m.group(0))
        m = re.search(r"\[.*\]", s, flags=re.DOTALL)
        if m:
            return json.loads(m.group(0))
        raise


def _max_tokens_fallback_from_error_message(msg: str) -> Optional[int]:
    s = (msg or "").lower()
    m = re.search(r"max(?:imum)?\s+(?:completion\s+)?tokens?\s*[:=]?\s*(\d+)", s)
    if m:
        try:
            return int(m.group(1))
        except Exception:
            return None
    m = re.search(r"must be\s*<=\s*(\d+)", s)
    if m:
        try:
            return int(m.group(1))
        except Exception:
            return None
    m = re.search(r"supports?\s+up to\s+(\d+)\s+tokens", s)
    if m:
        try:
            return int(m.group(1))
        except Exception:
            return None
    return None


async def _cerebras_chat_json(
    messages: List[Dict[str, str]],
    response_format: Dict[str, Any],
    temperature: float,
    top_p: float,
    max_completion_tokens: int,
) -> Any:
    client = _get_client()
    max_completion_tokens = int(max_completion_tokens)
    last_err: Optional[Exception] = None
    for _ in range(2):
        try:
            resp = await asyncio.to_thread(
                lambda: client.chat.completions.create(
                    model=CEREBRAS_MODEL,
                    messages=messages,
                    stream=False,
                    temperature=temperature,
                    top_p=top_p,
                    max_completion_tokens=max_completion_tokens,
                    response_format=response_format,
                    clear_thinking=CEREBRAS_CLEAR_THINKING,
                )
            )
            content = (resp.choices[0].message.content or "").strip()
            if not content:
                raise HTTPException(status_code=502, detail="Cerebras returned empty response")
            return _safe_json_loads(content)
        except Exception as e:
            last_err = e
            msg = str(e)
            fb = _max_tokens_fallback_from_error_message(msg)
            if fb and fb > 0 and fb < max_completion_tokens:
                max_completion_tokens = fb
                continue
            break
    raise HTTPException(status_code=502, detail=f"Cerebras error: {str(last_err) if last_err else 'unknown'}")


async def _cerebras_chat_text(
    messages: List[Dict[str, str]],
    temperature: float,
    top_p: float,
    max_completion_tokens: int,
) -> str:
    client = _get_client()
    max_completion_tokens = int(max_completion_tokens)
    last_err: Optional[Exception] = None
    for _ in range(2):
        try:
            resp = await asyncio.to_thread(
                lambda: client.chat.completions.create(
                    model=CEREBRAS_MODEL,
