@app.post("/v1/chat")
async def chat(req: ChatRequest, request: Request) -> Union[JSONResponse, StreamingResponse]:
    temperature = req.temperature if req.temperature is not None else CEREBRAS_TEMPERATURE_DEFAULT
    top_p = req.top_p if req.top_p is not None else CEREBRAS_TOP_P_DEFAULT
    temperature = float(temperature)
    top_p = float(top_p)
    normalized = _normalize_messages(req.messages, req.system_prompt)
    question = _last_user(normalized)

    if req.mode == "search":
        _require_env("EXA_API_KEY", EXA_API_KEY)
        context, sources = await _iterative_search_pipeline(question)
        final_messages = _build_final_messages(question, "search", context)

        if req.stream:
            async def gen() -> AsyncGenerator[str, None]:
                async for ev in _cerebras_stream_sse(request, final_messages, temperature, top_p, CEREBRAS_MAX_COMPLETION_TOKENS):
                    yield ev
            return StreamingResponse(gen(), media_type="text/event-stream")

        answer = await _cerebras_chat_text(final_messages, temperature, top_p, CEREBRAS_MAX_COMPLETION_TOKENS)
        if not _extract_citation_numbers(answer) and sources:
            answer = await _force_citations_pass(question, answer, context)
        return JSONResponse(ChatResponse(content=answer, sources=sources).model_dump())

    _require_env("PARALLEL_API_KEY", PARALLEL_API_KEY)
    processor = (req.parallel_processor or PARALLEL_DEFAULT_PROCESSOR).strip()
    if not processor:
        processor = PARALLEL_DEFAULT_PROCESSOR
    result = await _parallel_task_create_and_wait(question, processor)
    report_text, report_sources = _parallel_extract_text_and_citations(result)
    context = "PARALLEL_DEEP_RESEARCH_REPORT:\n" + report_text
    context = _soft_trim(context, FINAL_CONTEXT_SOFT_CHAR_BUDGET)
    final_messages = _build_final_messages(question, "research", context)

    if req.stream:
        async def gen() -> AsyncGenerator[str, None]:
            async for ev in _cerebras_stream_sse(request, final_messages, temperature, top_p, CEREBRAS_MAX_COMPLETION_TOKENS):
                yield ev
        return StreamingResponse(gen(), media_type="text/event-stream")

    answer = await _cerebras_chat_text(final_messages, temperature, top_p, CEREBRAS_MAX_COMPLETION_TOKENS)
    if not _extract_citation_numbers(answer) and report_sources:
        sources_context = _soft_trim(json.dumps(report_sources, ensure_ascii=False), FINAL_CONTEXT_SOFT_CHAR_BUDGET)
        answer = await _force_citations_pass(question, answer, sources_context)
    return JSONResponse(ChatResponse(content=answer, sources=report_sources).model_dump())


